// 直线距离
float dln(vec3 a, vec3 b, vec3 p){b-=a; p-=a;return length(p-b*clamp( dot(p,b)/dot(b,b),0.,1.));}

float smin(float a, float b, float k){ float h =clamp( .5*(a-b)/k+.5,  0.,1.); return mix(a,b,h)-k*h*(1.-h);} // 同时存在，
vec3 smin(vec3 a, vec3 b, float k)
{ 
     vec3 h =clamp( .5*(a-b)/k+.5,  0.,1.); 
     return mix(a,b,h)-k*h*(1.-h);
} 
vec3 smax(vec3 a, vec3 b, float k){ return smin(a, b,-k);} // 相交，取公共部分

// 交界处粘连， 多项式平滑
float smax(float a, float b, float k){ return smin(a, b,-k);} // 相交，取公共部分
float ssub(float a, float b, float k){ return smin(a,-b,-k);} // 抠去
mat3  rot3(vec3 n, float a){ n=normalize(n); float x=n.x, y=n.y, z=n.z, s=sin(a), c=cos(a), e=1.-c; return mat3(e*x*x+c, 

e*x*y+s*z, e*x*z-s*y, e*y*x-s*z, e*y*y+c, e*y*z+s*x, e*z*x+s*y, e*z*y-s*x, e*z*z+c);}

mat3 publicMmtr;vec3 clr;

float bx(vec3 p)
{
      return length( max(abs(p)-.8,0.));
}


float edg(int typ, float mx, vec3 p) // mx 面心距
{
        //vec3 n[3]=vec3[](n1,n2,n3);
        //vec3 n[5],f[4],x;  n[0]=n1;  n[1]=n2;  n[2]=n3; 
        vec3 n[5],f[4],x;
        /*
        n[0].z=2.;
        n[1]=vec3(sqrt(3.),0,1);  
        n[2]= vec3((n[0]+n[1]).xz/3.,sqrt(6.)/3.*2.).xzy;
        */
        // 等价，只是方向不同
        n[0]=vec3(0,1,1);   n[1]=vec3(1,0,1);   n[2]=vec3(1,1,0);
        for(int i;i<3;i++)n[i]=normalize(n[i]);
        n[3] = dot(n[0],n[1])*2.*n[0] - n[1];
        n[4] = dot(n[0],n[2])*2.*n[0] - n[2];


        // 三个六棱柱，互补于截角六面体

        clr=vec3(1);
        float md=1e8,d;

        vec3 q,c = n[0];
        for(int i;i<4;i++)
        {
                f[i]=c-n[i+1];
        }

        for(int j;j<3;j++)
                for(int i;i<4;i++)
                        if(dot(p,f[i])<0.)p=reflect(p, f[i]);
        d=length(p-c*mx)-.1;
        if(md>d)md=d,clr=vec3(0,0,1);
        if(typ==0)return d; // 法向量顶点

        //if(typ==1)return max(length(p.xy-c.xy),length(p)-mx); // 法向量
        d=max(length(p-dot(p,c)*c),length(p)-mx); // 这里还不是到直线的距离
        if(md>d)md=min(md,d),clr=vec3(0,1,1);
        if(typ==1)return d;

        vec3 h=normalize(n[1]+n[4]);
        float t=.5-.5*clamp(2.*cos(iTime),-1.,1.),
              s=1.5-t;

        //if(typ==2)return p.z-mx; // 返回平面 // dot() 
        d=dot(p,c)-mx*.49;
        d=max(d,max(dot(p,h)-s,    max(dot(p,h.yzx)-s,dot(p,h.zxy)-s)));
        //if(md>d)
        clr=smin(clr,vec3(1,.5,0),.6);
        //clr.y=smin(clr.y,vec3(1,.5,0).y,.06);
        //clr.z=smin(clr.z,vec3(1,.5,0).z,.06);
        md=smin(md,d,.6-.6*t);       
        if(typ==2)return d; // 返回平面 // dot() 


        //d =-1e8;
        d=1.;
        for(int i;i<4;i++)
        {
                q = p-normalize(c+n[i+1])*mx*.74;// 使四条交线都过原点
                x = cross(cross(c,n[i+1]),c); //c,x 三垂直
                vec2 u = vec2(dot(q, x),dot(q,c));
                d=smin(d, length(u),.08);
        }

        if(md>d)clr=vec3(1,.3,0)*2.;
                //clr=vec3(1);
        md=smin(d+.03,md,.5);
        if(typ==3)return d;


        d=1e8;

        for(int i;i<4;i++)
        {
                d= min(d, dln(c*mx*.95,(c-f[i])*mx*.95,p));//法向量连线
        }
        if(md>d)clr=vec3(1);//.8,.2,0);
                //clr=vec3(.8,1,0)*.6;
        md=smin(d,md,.3);
        //clr+=smin(clr,vec3(.8,.2,0),.6);


        if(typ==4)return d;


        return md;
}


// 场景
float sence(vec3 p)
{
      p *= publicMmtr;
      // SDF
      /*
      float d3=edg(0,1.5,p)-.1, // 法线顶点
      d4=edg(3,.9,p)-.05,  // 边界线
      d5=edg(4,1.5,p)-.05, // 补边线
      d2=edg(1,1.5,p)-.05, // 法线
      d1=edg(2,.6,p);// 实体
      */
      //return max(edg(2,2.,p),bx(p));

     // return min(d1,d5);


     return edg(6,2.,p)-.05;


      //return min(d4,min(min(d3,d4),smin(d2,d1,.6)));

      //return map(p);
}


void mainImage(out vec4 O, in vec2 v)
{
      publicMmtr = rot3(vec3(iTime*.7,iTime*.3,-iTime*.9),iTime);
      float d,t,m0=1e-3;
      vec2 R = iResolution.xy, u =(v+v-R)/R.y;
      vec3 o = vec3(0,0,-5),
             sun = normalize(vec3(-1,2,-3)),
             r=normalize(vec3(u,2)),
           e= vec3(0,m0*.1,0),
           n;
      O=normalize(vec4(8,7,6,5)); // 背景
      bool tui;
      for(int i;i++<200 && t < 20.;)
      {
                  d = sence(o + r*t);
                  if(d<m0) 
                  {
                              o = o + r*(t-m0);// m0 可以存一个历史 d
                              n = normalize(  vec3(sence(o+e.yxx),sence(o+e),sence(o+e.xxy))-sence(o) );
                              O = O*0. + dot(sun , n )*.5+.5; // 伪光照。
                              tui=true;
                              break;
                  }
                  t+=d*.7;
      }
      if(tui==false)clr=vec3(1);
      O.xyz*=clr;
}
